begin;set local statement_timeout='25s';select set_config('request.jwt.claim.sub','a5100000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $behavior$ declare plan jsonb;replayed jsonb;answer_list jsonb;first_result jsonb;retry_result jsonb;second_result jsonb;was_late boolean;
begin
if not (select paused from private.quiz_start_control where singleton) then raise exception 'not_paused';end if;
if not exists(select 1 from students where id='a5100000-0000-4000-8000-000000000002' and created_by='a5100000-0000-4000-8000-000000000001' and note='START-CONTROL-a510: 실제 학생 아님') then raise exception 'not_fake';end if;
plan:=public.begin_local_quiz_v1('a5100000-0000-4000-8000-000000000002','4647ed5a-4f22-47ad-8396-972e9e2263ac','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','4104fbe411d2c0198a01fbd4b4994e949c621589490bcb01cce6f21dc3838947');replayed:=public.begin_local_quiz_v1('a5100000-0000-4000-8000-000000000002','4647ed5a-4f22-47ad-8396-972e9e2263ac','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','4104fbe411d2c0198a01fbd4b4994e949c621589490bcb01cce6f21dc3838947');
if plan-'serverNow' is distinct from replayed-'serverNow' then raise exception 'start_replay_changed';end if;
select deadline_at<clock_timestamp() into was_late from quiz_attempts where id='4647ed5a-4f22-47ad-8396-972e9e2263ac';
if not was_late then raise exception 'late_fixture_not_late';end if;
select jsonb_agg(jsonb_build_object('id',item->>'id','order',ord,'kind','answer','choice',case when ord<=2 then ((item->>'correctChoiceIndex')::int+1)%4 else (item->>'correctChoiceIndex')::int end,'openedMs',(ord-1)*100,'elapsedMs',(ord-1)*100) order by ord) into answer_list from jsonb_array_elements(plan->'items') with ordinality x(item,ord);first_result:=public.submit_local_quiz_phase_v1('a5100000-0000-4000-8000-000000000002',(plan->>'attemptId')::uuid,plan->>'phase','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',plan->>'planHash','a5100000-0000-4000-8000-000000000950',answer_list,jsonb_build_object('elapsedMs',(jsonb_array_length(answer_list)-1)*100,'reason','answered'));
if first_result#>>'{result,state}'<>'retry_waiting' then raise exception 'retry_not_waiting';end if;
if first_result is distinct from public.submit_local_quiz_phase_v1('a5100000-0000-4000-8000-000000000002',(plan->>'attemptId')::uuid,plan->>'phase','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',plan->>'planHash','a5100000-0000-4000-8000-000000000950',answer_list,jsonb_build_object('elapsedMs',(jsonb_array_length(answer_list)-1)*100,'reason','answered')) then raise exception 'initial_replay_changed';end if;
plan:=public.begin_local_quiz_retry_v1('a5100000-0000-4000-8000-000000000002','4647ed5a-4f22-47ad-8396-972e9e2263ac','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa');
select jsonb_agg(jsonb_build_object('id',item->>'id','order',ord,'kind','answer','choice',case when ord<=0 then ((item->>'correctChoiceIndex')::int+1)%4 else (item->>'correctChoiceIndex')::int end,'openedMs',(ord-1)*100,'elapsedMs',(ord-1)*100) order by ord) into answer_list from jsonb_array_elements(plan->'items') with ordinality x(item,ord);retry_result:=public.submit_local_quiz_phase_v1('a5100000-0000-4000-8000-000000000002',(plan->>'attemptId')::uuid,plan->>'phase','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',plan->>'planHash','a5100000-0000-4000-8000-000000000951',answer_list,jsonb_build_object('elapsedMs',(jsonb_array_length(answer_list)-1)*100,'reason','answered'));
if (retry_result#>>'{result,attempt,finalScore}')::numeric<>100 or retry_result#>>'{result,attempt,passed}'<>'true' then raise exception 'retry_result_failed';end if;
if retry_result is distinct from public.submit_local_quiz_phase_v1('a5100000-0000-4000-8000-000000000002',(plan->>'attemptId')::uuid,plan->>'phase','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',plan->>'planHash','a5100000-0000-4000-8000-000000000951',answer_list,jsonb_build_object('elapsedMs',(jsonb_array_length(answer_list)-1)*100,'reason','answered')) then raise exception 'retry_replay_changed';end if;
plan:=public.begin_local_quiz_v1('a5100000-0000-4000-8000-000000000002','e9ed6127-4117-4dd9-bbb1-4da9113409a6','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','67d728bdfc27a05325f32c020a8f5514c712fd255ddcf9190e6323d78de4b771');select jsonb_agg(jsonb_build_object('id',item->>'id','order',ord,'kind','answer','choice',case when ord<=0 then ((item->>'correctChoiceIndex')::int+1)%4 else (item->>'correctChoiceIndex')::int end,'openedMs',(ord-1)*100,'elapsedMs',(ord-1)*100) order by ord) into answer_list from jsonb_array_elements(plan->'items') with ordinality x(item,ord);second_result:=public.submit_local_quiz_phase_v1('a5100000-0000-4000-8000-000000000002',(plan->>'attemptId')::uuid,plan->>'phase','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',plan->>'planHash','a5100000-0000-4000-8000-000000000952',answer_list,jsonb_build_object('elapsedMs',(jsonb_array_length(answer_list)-1)*100,'reason','answered'));
if (second_result#>>'{result,attempt,finalScore}')::numeric<>100 then raise exception 'second_result_failed';end if;
begin perform public.begin_local_quiz_v1('a5100000-0000-4000-8000-000000000002','1bd69af3-b28a-443f-8fc1-268ab5e8e441','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','c8361363267e0a6f61e9d64e98739daed1b726b2e3f4458eb803025fd19c75fc');raise exception 'new_start_unexpectedly_allowed';exception when sqlstate '55000' then if sqlerrm<>'quiz_new_attempts_paused' then raise;end if;end;
if exists(select 1 from quiz_attempts where id='1bd69af3-b28a-443f-8fc1-268ab5e8e441') or exists(select 1 from private.quiz_attempt_preparations where id='1bd69af3-b28a-443f-8fc1-268ab5e8e441' and begun_id is not null) then raise exception 'refused_start_left_rows';end if;
perform set_config('start_control.behavior',jsonb_build_object('wasLate',was_late,'initial',first_result,'retry',retry_result,'second',second_result,'refusedPreparation','1bd69af3-b28a-443f-8fc1-268ab5e8e441','newAttemptCount',0,'checkedAt',clock_timestamp())::text,true);
end $behavior$;
select current_setting('start_control.behavior')::jsonb value;commit;
